#!/bin/bash
# ITEM 6a, Jack 25 Nov: the full exit factorial on the best book members.
# 4 exit arms x 3 stops x 3 targets x 2 trails x 4 time stops = 288 cells per
# member, A and B = 576 walk-forward stitches. Resumable per cell.
#
# DO NOT EDIT THIS FILE WHILE IT IS RUNNING. Bash reads a script incrementally
# as it executes, so inserting lines in the middle of a running driver moves
# the byte offset it will resume from and can corrupt the rest of the run. It
# was edited once at 11:45 on 25 Nov while the sweep was live and then
# restored byte-for-byte; the follow-up steps live in exit6b.sh for exactly
# this reason.
cd "$(dirname "$0")/../.." || exit 1
export FX_COST_TABLE=results/cost_table_h22.csv
LOG=results/chainlogs/exit6.log
say(){ echo "[$(date +%H:%M:%S)] $*" | tee -a $LOG; }
say "START exit6"
python3 code/nnfxexit.py --stage sweep >>$LOG 2>&1 && say "OK exit6" || { say "FAIL exit6"; exit 1; }
say "DONE exit6"
